using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class WalkSector {
 static Vector3 V(float x,float z)=>new Vector3(-15+x,-82,-10+z);
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var oldPos=player.transform.position;bool oldEnabled=cc.enabled;var results=new List<object>();
 var routes=new[]{new{name="living_centre",pts=new[]{V(0,-1.8f),V(0,.2f),V(.7f,.5f),V(.7f,-1.8f)}},new{name="bed_aisle",pts=new[]{V(-.7f,-1.8f),V(-.7f,.8f)}},new{name="sanitary_access",pts=new[]{V(.8f,.7f),V(.9f,2.6f),V(.2f,3.25f)}},new{name="desk_approach",pts=new[]{V(.4f,-1.8f),V(1.5f,-1.6f)}},new{name="outer_east",pts=new[]{V(6.1f,-3),V(6.1f,3)}},new{name="outer_west",pts=new[]{V(-6.1f,-3),V(-6.1f,3)}},new{name="staff_passage",pts=new[]{V(-5.5f,-7),V(5.4f,-7)}},new{name="north_entry",pts=new[]{new Vector3(-17.23f,-82,0),new Vector3(-17.23f,-82,-3.4f)}}};
 try{foreach(var route in routes){cc.enabled=false;player.transform.position=route.pts[0]+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();float maxError=0;int steps=0;var segments=new List<object>();for(int j=1;j<route.pts.Length;j++){var to=route.pts[j];for(int i=0;i<600;i++){Vector3 delta=to-player.transform.position;delta.y=0;if(delta.magnitude<.05f)break;cc.Move(delta.normalized*.025f+Vector3.down*.08f);steps++;}var feet=player.transform.position+Vector3.up*(cc.center.y-cc.height*.5f);float error=Vector2.Distance(new Vector2(feet.x,feet.z),new Vector2(to.x,to.z));maxError=Mathf.Max(maxError,error);segments.Add(new{target=to.ToString(),feet=feet.ToString(),remaining=error,heightError=Mathf.Abs(feet.y+82)});}results.Add(new{route.name,steps,maxError,passed=maxError<.10f,segments});}}
 finally{cc.enabled=false;player.transform.position=oldPos;cc.enabled=oldEnabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}
 File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-06_B5_Sector01/controller_walk.json")),JsonConvert.SerializeObject(results,Formatting.Indented));return results;}
}
